<section class="mn-hero"><div class="mn-w mn-hero-g"><div class="mn-hero-t"><p class="mn-ey">Right now</p><p class="mn-now" id="now" aria-live="off">It is just past the hour.</p><h1>Minute</h1><p class="mn-hero-p">An independent guide to the smallest unit on the dial that matters: how to read it, how watches keep it and how to keep yours accurate.</p><a class="mn-btn" href="#read">Read a dial</a></div><div class="mn-hero-d"><svg viewBox="0 0 400 400" aria-hidden="true"><circle cx="200" cy="200" r="196" class="rim"/><line x1="200" y1="14" x2="200" y2="40" transform="rotate(0 200 200)" class="tk tk5" data-i="0"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(6 200 200)" class="tk" data-i="1"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(12 200 200)" class="tk" data-i="2"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(18 200 200)" class="tk" data-i="3"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(24 200 200)" class="tk" data-i="4"/><line x1="200" y1="14" x2="200" y2="40" transform="rotate(30 200 200)" class="tk tk5" data-i="5"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(36 200 200)" class="tk" data-i="6"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(42 200 200)" class="tk" data-i="7"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(48 200 200)" class="tk" data-i="8"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(54 200 200)" class="tk" data-i="9"/><line x1="200" y1="14" x2="200" y2="40" transform="rotate(60 200 200)" class="tk tk5" data-i="10"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(66 200 200)" class="tk" data-i="11"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(72 200 200)" class="tk" data-i="12"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(78 200 200)" class="tk" data-i="13"/><line x1="200" y1="14" x2="200" y2="30" transform="rotate(84 200 200)" class="tk" data-i="14"/><line x1="200" y1="14" x2="200" y2="40" transform="rot